import {referencePage,state as viewState,applyAppearance,changeAppearance} from './reference-views.mjs';
import {icon} from './icons.mjs';
import {esc as e,bytes,when,kindLabels,safeURL,model,validateSnapshot} from './model.mjs';
const $=s=>document.querySelector(s);
const get=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('vovan:'+key))??fallback}catch{return fallback}};
const put=(key,value)=>{try{localStorage.setItem('vovan:'+key,JSON.stringify(value));return true}catch{toast('Не удалось сохранить: хранилище браузера заполнено.');return false}};
let snapshot, data, route=location.hash.slice(1)||'home', query='', mapFilter='all', projectFilter='all', dbFilter='all',selectedServer=get('server','78'),custom=get('projects',[]),tasks=get('tasks',[]),compact=get('compact',false),lastRead=null,graphType='all',graphSelected=null;
const nav=[['home','home','Главная'],['projects','box','Проекты'],['agents','brain','ИИ-агенты'],['sites','site','Сайты'],['games','game','Игры'],['bots','bot','Боты'],['files','folder','Файлы'],['databases','db','Базы данных'],['deploys','rocket','Деплои'],['analytics','chart','Аналитика'],['settings','settings','Настройки']];
const meta={
'eeklera-site':['EEKLERA','globe','cyan','Сайт / Медиа / ИИ'],
'vovan-app':['Vovan App','phone','blue','Соцсеть / Чаты / Медиа'],
'kabluk':['Kabluk','city','cyan','Онлайн-город / Экономика'],
'video2md':['Video2MD','video','blue','Видео / Транскрибация'],
'twitch-manager':['Twitch Manager','twitch','purple','Стримы / Боты / Аналитика'],
'modbot':['ModBot','bot','blue','Модерация / Telegram'],
'auth-gateway':['Auth Gateway','shield','blue','Авторизация / Безопасность'],
'exchange':['Exchange','exchange','purple','Обмен / Файлы'],
'studio':['Studio','palette','purple','Сайты / Дизайн'],
'graph':['Graph','chart','purple','Карта / Визуализация'],
'orion':['Orion','brain','purple','Память / Задачи / Интеллект'],
 'terraria':['Terraria Server','leaf','green','Плагины / Мир / Сервер'],
 'sentra':['Sentra','box','green','Ядро / API / Данные'],
 'agent-hub':['Agent Hub','brain','purple','Агенты / Рабочие пространства'],
 'jarvis':['Jarvis','brain','purple','Ассистент / Автоматизация']};
const look=p=>meta[p.id]||[p.name,({game:'game',site:'globe',app:'phone',agents:'brain',bot:'bot',infra:'server',archive:'folder'})[p.kind]||'box',p.kind==='agents'?'purple':'cyan',kindLabels[p.kind]||'Проект'];
const statusLabel=p=>({active:'Работал',partial:'Частично',inactive:'Остановлен',live:'Сайт в снимке',stopped:'Не запущен','repo-only':'Только GitHub',lost:'Файлы утрачены',idea:'Идея / архив',empty:'Пустой',unknown:p.local?'Локальный':'Не подтверждён'}[p.status]||'Неизвестно');
const status=p=>`<span class="status ${p.status||'unknown'}" title="Состояние на дату снимка"><i></i>${statusLabel(p)}</span>`;
function project(id){return data.projects.find(p=>p.id===id)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function download(name,obj){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function button(label,action,ico='',cls=''){return `<button class="button ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`}
function empty(title,desc,ico='server',action=''){return `<div class="empty">${icon(ico)}<h3>${title}</h3><p>${desc}</p>${action}</div>`}
function sectionTitle(title,sub='',actions=''){return `<div class="section-title"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="section-actions">${actions}</div></div>`}
function external(url,label){const u=safeURL(url);return u?`<a class="external" href="${e(u)}" target="_blank" rel="noopener noreferrer">${e(label)}${icon('external')}</a>`:e(label)}
function smallHeader(title,ico,action,label='Открыть'){return `<div class="panel-heading"><h2>${icon(ico)}${title}</h2>${action?`<button class="text-button" data-action="${action}">${label}${icon('chevron')}</button>`:''}</div>`}
function serverMetrics(){return snapshot.servers[selectedServer]||Object.values(snapshot.servers)[0]}
function sidebar(){
 const s=serverMetrics(), h=s.host,disk=h.disks.find(d=>d.mount==='/'),ram=(h.ram_total-h.ram_available)/h.ram_total*100;
 return `<aside class="sidebar"><a class="brand" href="#home" aria-label="Vovan OS, главная">VOVAN <span>OS</span><small>Единая система всех проектов</small></a><nav aria-label="Разделы">${nav.map(([id,ic,label])=>`<a href="#${id}" class="nav-item ${route===id?'selected':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</nav><div class="my-projects"><div class="eyebrow">МОИ ПРОЕКТЫ<button data-action="new-project" aria-label="Добавить проект">${icon('plus')}</button></div>${['eeklera-site','vovan-app','kabluk','terraria','orion'].map(id=>{const p=project(id);return p?`<button class="project-shortcut" data-project="${id}"><i class="tiny-dot ${p.status}"></i><span class="${look(p)[2]}">${icon(look(p)[1])}</span>${look(p)[0]}</button>`:''}).join('')}</div><div class="sidebar-bottom"><button class="user" data-action="profile"><span class="avatar">V</span><span><strong>Vovan</strong><small>Владелец</small></span>${icon('bell')}</button><div class="system-label"><i></i><div>Локальная система<small>Снимок · ${e(when(s.collected_at))}</small></div></div><label class="server-select">Сервер <select id="server-select" aria-label="Сервер для показателей">${Object.keys(snapshot.servers).sort().map(id=>`<option value="${id}" ${id===selectedServer?'selected':''}>${id}</option>`).join('')}</select></label><div class="meter-row"><span title="Средняя нагрузка за минуту; это не процент CPU">Load</span><div class="meter"><i style="width:${Math.min(100,h.load[0]/h.cpus*100)}%"></i></div><b>${h.load[0].toFixed(2)}</b></div><div class="meter-row"><span>RAM</span><div class="meter"><i style="width:${ram}%"></i></div><b>${Math.round(ram)}%</b></div><div class="meter-row"><span>Диск /</span><div class="meter blue"><i style="width:${disk.used/disk.size*100}%"></i></div><b>${Math.round(disk.used/disk.size*100)}%</b></div></div></aside>`
}
function shell(){
 document.body.classList.toggle('quiet',compact);
 $('#app').innerHTML=`${sidebar()}<div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><label class="search-box">${icon('search')}<input id="global-search" type="search" placeholder="Поиск по проектам, сервисам, базам…" value="${e(query)}" autocomplete="off" aria-label="Поиск по системе"><kbd>Ctrl K</kbd></label><span class="local-badge">${icon('lock')} ЛОКАЛЬНО</span><div class="header-right"><button class="icon-button" data-action="quiet" aria-label="${compact?'Включить':'Уменьшить'} свечение" title="Мягкое свечение">${icon('moon')}</button><div class="header-date">${icon('globe')}<div>Моя система<small>${new Intl.DateTimeFormat('ru',{day:'numeric',month:'short',year:'numeric'}).format(new Date())}</small></div></div>${button('Создать проект','new-project','plus','primary')}</div></header><main id="main" tabindex="-1"></main><footer class="footer"><span>VOVAN OS <i>•</i> Локальное хранилище</span><button data-action="refresh">${icon('refresh')} Обновить снимок</button><span>Источник: ${e(snapshot.source.repository)} · ${e(snapshot.source.commit.slice(0,7))}</span></footer></div>`;
 renderPage();
}
function renderPage(){
 const pages={home:home,projects:()=>projectsPage(),agents:()=>projectsPage(['agents'],'ИИ-агенты'),sites:()=>projectsPage(['site'],'Сайты'),games:()=>projectsPage(['game'],'Игры'),bots:()=>projectsPage(['bot'],'Боты'),files:filesPage,databases:databasesPage,deploys:deploysPage,analytics:analyticsPage,settings:settingsPage,services:servicesPage,github:githubPage,graph:graphPage,tasks:tasksPage,logs:logsPage,alerts:alertsPage};
 applyAppearance(); $('#main').innerHTML=query.trim()?searchPage(): (referencePage(route,{data,snapshot,tasks,projectFilter,dbFilter,look,status,compact}) ?? (pages[route]||pages.home)());
 document.title=(nav.find(n=>n[0]===route)?.[2]||'Центр управления')+' · VOVAN OS';
}
function home(){
 const disks=Object.values(snapshot.servers).flatMap(s=>s.host.disks),used=disks.reduce((n,d)=>n+d.used,0),total=disks.reduce((n,d)=>n+d.size,0),deployTimers=data.timers.filter(t=>t.timer.includes('deploy'));
 const stats=[['Проекты',data.projects.length,`${snapshot.repos.length} репозиториев`,'box','blue','projects'],['Сервисы онлайн',data.activeServices,`из ${data.services.length} · в снимке`,'wifi','cyan','services'],['Активные агенты','—','Не подключено','brain','purple','agents'],['Хранилище',bytes(used),`из ${bytes(total)} · тома серверов`,'db','blue','analytics'],['Деплои',deployTimers.length,'таймера · результаты не подключены','rocket','green','deploys'],['Ошибки','—','Живые проверки не подключены','alert','pink','alerts']];
 return `<div class="stats-grid">${stats.map(([label,value,sub,ic,c,r])=>`<button class="stat-card ${c}" data-route="${r}"><span class="stat-icon">${icon(ic)}</span><div><span class="stat-label">${label}</span><strong>${value}</strong><small>${sub}</small></div>${r==='analytics'?`<div class="stat-meter"><i style="width:${used/total*100}%"></i></div>`:''}</button>`).join('')}</div><div class="dashboard-grid"><div class="main-column"><section class="panel system-map"><div class="map-heading"><div><h2>Карта системы</h2><p>Все проекты в единой экосистеме</p></div><div class="filter-pills" role="group" aria-label="Фильтр карты">${[['all','Все'],['project','Проекты'],['service','Сервисы'],['agents','Агенты'],['infra','Инфраструктура']].map(([v,t])=>`<button class="${mapFilter===v?'active':''}" data-mapfilter="${v}" aria-pressed="${mapFilter===v}">${t}</button>`).join('')}</div></div>${overviewMap()}<div class="map-foot"><span>${icon('clock')} Снимок ${e(when(snapshot.servers['78']?.collected_at||serverMetrics().collected_at))}</span><button class="text-button" data-route="graph">Все ${data.graph.nodes.length} объектов ${icon('expand')}</button></div></section><section class="featured"><div class="featured-heading"><div><h2>Основные проекты</h2><p>Ключевые проекты экосистемы</p></div><button class="text-button" data-route="projects">Все проекты ${icon('chevron')}</button></div><div class="featured-grid">${['eeklera-site','kabluk','terraria','orion','vovan-app'].map((id,i)=>project(id)?featureCard(project(id),i):'').join('')}</div></section></div><aside class="right-column"><section class="panel git-widget">${smallHeader('Git / Репозитории','git','route-github')}<div class="panel-sub">${snapshot.repos.length} репозиториев в снимке</div><div class="commit-list">${['vovan-app','eeklera-online','orion'].map(name=>{const r=snapshot.repos.find(r=>r.name===name);return r?`<button data-repo="${e(name)}"><i></i><span>${e(name)}<small>${e(r.default_branch)} · ${r.visibility==='private'?'Приватный':'Публичный'}</small></span><b>${bytes(r.size_kib*1024,0)}</b></button>`:''}).join('')}</div></section><section class="panel logs-widget">${smallHeader('Логи сервера','server','route-logs')}<div class="panel-sub">Подключение к серверу</div><div class="terminal-empty"><span class="terminal-line">${icon('lock')} LOCAL / READ ONLY</span><p>Поток логов ещё не подключён</p><small>Сервисы и их состояние доступны в снимке.</small></div><button class="text-button" data-route="services">Посмотреть сервисы ${icon('chevron')}</button></section><section class="panel ai-widget">${smallHeader('AI Gateway','brain','route-agents')}<div class="panel-sub">Модели и агенты</div><div class="not-connected"><div class="wave-placeholder" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="height:${[9,13,18,11,24,18,30,23][i%8]}px"></i>`).join('')}</div><strong>—<small>запросов / мин</small></strong></div><div class="muted-small">Нет источника метрик</div></section><section class="panel tasks-widget">${smallHeader('Очередь задач','list','route-tasks')}<div class="panel-sub">${tasks.filter(t=>!t.done).length} локальных задач</div>${tasks.length?`<div class="mini-tasks">${tasks.slice(0,3).map(t=>`<label><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''}><span class="${t.done?'done':''}">${e(t.title)}</span></label>`).join('')}</div>`:`<div class="mini-empty">Всё спокойно. Новых задач нет.</div>`}<button class="text-button" data-action="new-task">${icon('plus')} Добавить задачу</button></section><section class="panel deploy-widget">${smallHeader('Последний деплой','rocket','route-deploys')}<div class="deploy-placeholder"><span>Нет данных о результате</span><small>Есть ${deployTimers.length} таймера автодеплоя</small></div></section></aside></div>`
}
function overviewMap(){
 const base=[['eeklera-site',23,16],['vovan-app',50,11],['kabluk',77,16],['video2md',16,34],['terraria',84,34],['twitch-manager',13,53],['orion',87,53],['modbot',17,72],['graph',84,72],['auth-gateway',27,90],['exchange',51,90],['studio',75,90]];
 let positions=base;
 if(mapFilter!=='all'){
  const ids=mapFilter==='agents'?['agent-hub','orion','jarvis','lera-assistant']:mapFilter==='infra'?['auth-gateway','sentra','vpn','streaming','graph']:mapFilter==='service'?['video2md','exchange','modbot','sentra','beaver','eeklera-services']:['eeklera-site','vovan-app','kabluk','terraria','studio','eeklera-os'];
  const slots=[[22,20],[78,20],[18,51],[82,51],[25,83],[75,83]];
  positions=ids.map((id,i)=>[id,...slots[i]]);
 }
 const active=positions.filter(([id])=>project(id));
 return `<div class="map-viewport"><div class="overview-canvas"><svg class="map-links" viewBox="0 0 1000 540" preserveAspectRatio="none" aria-hidden="true"><defs><filter id="glow"><feGaussianBlur stdDeviation="2"/></filter></defs>${active.map(([id,x,y],i)=>{const ex=x*10,ey=y*5.4,side=x<50?-1:1;const sx=500+side*85,sy=270+(ey-270)*.25;const line=`M${sx} ${sy} L${500+side*145} ${ey} L${ex} ${ey}`;return `<path d="${line}" class="glow-line"/><path d="${line}" class="core-line"/><circle cx="${500+side*145}" cy="${ey}" r="3"/>`}).join('')}</svg><button class="globe-core" data-route="graph" aria-label="Открыть полную карту системы"><img src="./assets/interface-art.png" alt="" draggable="false"><span class="globe-label"><strong>VOVAN <b>OS</b></strong><small>Единая система<br>всех проектов</small></span></button>${active.map(([id,x,y])=>{const p=project(id),[name,ic,c,sub]=look(p);return `<button class="map-node ${c}" style="left:${x}%;top:${y}%" data-project="${e(id)}" title="${e(p.name)} · ${statusLabel(p)} в снимке"><span class="map-icon">${icon(ic)}</span><span class="node-label"><strong>${e(name)}</strong><small>${e(sub)}</small></span><i class="node-status ${p.status}"></i></button>`}).join('')}</div></div>`
}
function featureCard(p,i){const [name,ic,c,sub]=look(p);return `<button class="feature-card" data-project="${e(p.id)}"><div class="card-art art-${i}"><img src="./assets/interface-art.png" alt="" draggable="false"></div><div class="feature-content">${status(p)}<div class="feature-label"><h3>${e(name)}</h3><p>${e(sub)}</p></div><div class="feature-bottom"><span><b>${(p.matchedServices.length+p.matchedContainers.length)||'—'}</b><small>сервисов</small></span><span><b>${(p.databases||[]).length||'—'}</b><small>баз данных</small></span><span class="card-open">${icon('chevron')}</span></div></div></button>`}
function projectsPage(kinds=null,title='Проекты'){
 const filter=p=>(!kinds||kinds.includes(p.kind))&&(projectFilter==='all'||p.status===projectFilter);
 const arr=data.projects.filter(filter);
 return sectionTitle(title,`${arr.length} проектов · состояние на дату снимка`,button('Создать проект','new-project','plus','primary'))+`<div class="toolbar"><div class="filter-pills">${[['all','Все'],['active','Работали'],['live','Сайты'],['stopped','Не запущены'],['repo-only','GitHub'],['lost','Утрачены'],['idea','Идеи / архив']].map(([v,t])=>`<button data-projectfilter="${v}" class="${projectFilter===v?'active':''}">${t}</button>`).join('')}</div><span class="muted-small">${snapshot.catalog?.projects.length||data.projects.length} в каталоге · ${custom.length} локальных</span></div><div class="project-grid">${arr.map(projectTile).join('')}</div>${arr.length?'':empty('Пока нет проектов','Попробуйте другой фильтр.','box')}`
}
function projectTile(p){const [name,ic,c]=look(p);return `<button class="project-tile panel" data-project="${e(p.id)}"><div class="tile-top"><span class="tile-icon ${c}">${icon(ic)}</span>${status(p)}</div><h2>${e(name)}</h2><p>${e(p.note||p.repoInfo?.description||kindLabels[p.kind]||'Локальный проект')}</p><div class="tile-meta"><span>${icon('git')}${e(p.repo||'Без репозитория')}</span><span>${icon('server')}${e(p.server||'Локально')}</span></div>${['low','medium'].includes(p.confidence)?`<small class="confidence">${icon('alert')} Связь ${p.confidence==='low'?'предварительная':'требует проверки'}</small>`:''}</button>`}
function servicesPage(){return sectionTitle('Сервисы',`${data.services.length} systemd · ${data.containers.length} контейнера · снимок ${when(serverMetrics().collected_at)}`)+`<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Сервис</th><th>Сервер</th><th>Состояние в снимке</th><th>Порт</th><th>Память</th><th>Перезапуски</th></tr></thead><tbody>${data.services.map(s=>`<tr><td><button class="table-link" data-service="${e(s.server+':'+s.name)}">${icon('server')}${e(s.name)}</button><small>${e(s.description)}</small></td><td>${s.server}</td><td><span class="status ${s.state==='active'?'active':'inactive'}"><i></i>${e(s.state)}</span></td><td>${e((s.ports||[]).map(p=>p[0]).join(', ')||'—')}</td><td>${bytes(s.memory)}</td><td>${s.restarts??'—'}</td></tr>`).join('')}</tbody></table></div></section><h2 class="subheading">Контейнеры</h2><div class="project-grid">${data.containers.map(c=>`<div class="panel info-card"><h3>${icon('box')}${e(c.name)}</h3><p>${e(c.image)}</p><span class="status ${/^Up/.test(c.status)?'active':'unknown'}"><i></i>${e(c.status)}</span><dl><dt>Сервер</dt><dd>${c.server}</dd><dt>Порты</dt><dd>${e(c.ports||'—')}</dd></dl></div>`).join('')}</div>`}
function databasesPage(){const arr=data.databases.filter(d=>dbFilter==='all'||d.engine===dbFilter);return sectionTitle('Базы данных',`${data.databases.filter(d=>!d.system).length} прикладных · ${data.databases.filter(d=>d.system).length} системная · только структура и число строк`)+`<div class="toolbar"><div class="filter-pills">${['all','postgres','sqlite','redis'].map(v=>`<button data-dbfilter="${v}" class="${dbFilter===v?'active':''}">${v==='all'?'Все':v==='postgres'?'PostgreSQL':v==='sqlite'?'SQLite':'Redis'}</button>`).join('')}</div></div><div class="database-grid">${arr.map(db=>`<button class="panel database-card" data-db="${e(db.id)}"><span class="db-icon ${db.engine==='postgres'?'blue':db.engine==='redis'?'pink':'cyan'}">${icon('db')}</span><div><span class="eyebrow">${e(db.engine)} ${db.system?'· СИСТЕМНАЯ':''}</span><h2>${e(db.name)}</h2><p class="mono">${e(db.path||db.container)}</p><div class="db-stats"><span><b>${db.engine==='redis'?'—':db.tables.length}</b> таблиц</span><span><b>${bytes(db.size)}</b></span><span>Сервер ${db.server}</span></div></div>${icon('chevron')}</button>`).join('')}</div>`}
function githubPage(){return sectionTitle('GitHub / Репозитории',`${snapshot.repos.length} репозиториев · сохранённые метаданные`,button('Обновить снимок','refresh','refresh'))+`<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Репозиторий</th><th>Доступ</th><th>Ветка</th><th>Размер GitHub</th><th>Проект</th></tr></thead><tbody>${snapshot.repos.map(r=>`<tr><td>${external(r.url,r.name)}<small>${e(r.description)}</small></td><td>${r.visibility==='private'?'Приватный':'Публичный'}</td><td><code>${e(r.default_branch)}</code></td><td>${bytes(r.size_kib*1024)}</td><td><button class="text-button" data-project="${e(data.projects.find(p=>(p.catalog?.repos||[{name:p.repo}]).some(pr=>pr.name===r.name))?.id||'')}">Открыть карточку ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div></section><p class="page-note">История коммитов не входит в текущий снимок. Размер GitHub не равен размеру рабочей базы.</p>`}
function filesPage(){return sectionTitle('Файлы и хранилища',`${data.apps.length} каталогов приложений на двух серверах · содержимое файлов не загружено`)+`<div class="summary-cards">${Object.entries(snapshot.servers).map(([id,s])=>`<div class="panel info-card"><h2>${icon('server')}Сервер ${id}</h2><p>${s.apps.length} каталогов · ${bytes(s.apps.reduce((n,a)=>n+(a.size||0),0))} суммарно</p><small>Размеры вложенных каталогов могут пересекаться.</small></div>`).join('')}</div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Каталог</th><th>Сервер</th><th>Размер</th><th>Стек</th><th>Git</th></tr></thead><tbody>${data.apps.map((a,i)=>`<tr><td><button class="table-link" data-app="${i}">${icon('folder')}${e(a.name)}</button><small class="mono">${e(a.path)}</small></td><td>${a.server}</td><td>${bytes(a.size)}</td><td>${e((a.stack||[]).join(', ')||'—')}</td><td>${a.git?'Обнаружен':'Не обнаружен'}</td></tr>`).join('')}</tbody></table></div></section>`}
function deploysPage(){return sectionTitle('Деплои и резервные копии','Настроенные расписания из снимка. Результаты запусков ещё не подключены.')+`<div class="summary-cards"><div class="panel">${empty('Последний деплой неизвестен','Таймер показывает расписание, но не подтверждает успешное обновление.','rocket')}</div><div class="panel info-card"><span class="eyebrow">РАСПИСАНИЯ</span><strong class="large-value">${data.timers.filter(t=>t.timer.includes('deploy')).length}</strong><p>таймера автоматического деплоя</p></div></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Таймер</th><th>Сервер</th><th>Назначение</th><th>Последнее срабатывание</th></tr></thead><tbody>${data.timers.map(t=>`<tr><td><code>${e(t.timer)}</code></td><td>${t.server}</td><td>${e(t.description)}</td><td>${e(t.last||'Нет данных')}</td></tr>`).join('')}</tbody></table></div></section><h2 class="subheading">Найденные резервные копии</h2><div class="project-grid">${Object.entries(snapshot.servers).flatMap(([id,s])=>s.backups.map(b=>`<div class="panel info-card"><h3>${icon('folder')}Сервер ${id}</h3><p class="mono">${e(b.dir)}</p><dl><dt>Объём</dt><dd>${bytes(b.size)}</dd><dt>Файлов</dt><dd>${b.files}</dd><dt>Последний</dt><dd>${e(b.latest)}</dd><dt>Изменён</dt><dd>${e(b.latest_at)}</dd></dl></div>`)).join('')}</div>`}
function analyticsPage(){return sectionTitle('Серверы и аналитика','Измерения из снимка. История нагрузки и живой CPU пока не подключены.')+`<div class="server-grid">${Object.entries(snapshot.servers).map(([id,s])=>{const h=s.host,ram=h.ram_total-h.ram_available;return `<section class="panel server-card"><div class="server-head"><span class="tile-icon cyan">${icon('server')}</span><div><h2>Сервер ${id}</h2><p>${e(h.hostname)} · ${e(h.public_ip)}</p></div><span class="snapshot-tag">Снимок</span></div><p>${e(h.os)} · ${h.cpus} vCPU</p><div class="metric-block"><span>Память <b>${bytes(ram)} / ${bytes(h.ram_total)}</b></span><div class="meter"><i style="width:${ram/h.ram_total*100}%"></i></div></div><div class="load-metrics">${h.load.map((n,i)=>`<div><strong>${n.toFixed(2)}</strong><span>Load · ${[1,5,15][i]} мин</span></div>`).join('')}</div><p class="muted-small">Load — средняя очередь процессов, не процент загрузки CPU.</p><h3>Диски</h3>${h.disks.map(d=>`<div class="metric-block"><span><code>${e(d.mount)}</code><b>${bytes(d.used)} / ${bytes(d.size)}</b></span><div class="meter ${d.used/d.size>.85?'warning':'blue'}"><i style="width:${d.used/d.size*100}%"></i></div><small>Доступно ${bytes(d.avail)}</small></div>`).join('')}<div class="server-foot"><span>${Math.floor(h.uptime_s/86400)} д. работы</span><span>${e(when(s.collected_at))}</span></div></section>`}).join('')}</div><h2 class="subheading">Сертификаты</h2><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Имя</th><th>Домены</th><th>Сервер</th><th>Действует до</th></tr></thead><tbody>${Object.entries(snapshot.servers).flatMap(([id,s])=>s.certs.map(c=>`<tr><td>${e(c.name)}</td><td>${e(c.domains.join(', '))}</td><td>${id}</td><td>${e(c.expires)}</td></tr>`)).join('')}</tbody></table></div></section>`}
function logsPage(){return sectionTitle('Логи сервера','Доступ только для чтения')+`<section class="panel">${empty('Живой поток ещё не подключён','В репозитории сохранены сервисы и схемы, но нет журнала событий. Подключение будущего API добавит реальные логи сюда.','server',button('Открыть список сервисов','route-services','server'))}</section>`}
function alertsPage(){const problems=data.projects.flatMap(p=>(p.catalog?.problems||[]).map(note=>({p,note})));return sectionTitle('Ошибки и проверки',`${problems.length} замечаний в каталоге · это не текущие аварии`)+`<div class="panel info-card"><h2>${icon('alert')}Проверки из сохранённого снимка</h2><p>Здесь собраны отсутствующие файлы, сломанные ссылки и другие замечания из паспорта проектов. Живой мониторинг пока не подключён.</p></div><div class="project-grid alerts-grid">${problems.map(({p,note})=>`<button class="panel info-card alert-card" data-project="${e(p.id)}"><h3>${icon('alert')}${e(p.name)}</h3><p>${e(note)}</p><small>${statusLabel(p)} · открыть паспорт</small></button>`).join('')}</div>`}
function tasksPage(){return sectionTitle('Мои задачи','Хранятся только в этом браузере',button('Добавить задачу','new-task','plus','primary'))+`<section class="panel task-list">${tasks.length?tasks.map(t=>`<div class="task-row"><label><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''}><span class="${t.done?'done':''}">${e(t.title)}<small>${e(project(t.project)?.name||'Общая задача')}</small></span></label><button class="icon-button" data-delete-task="${e(t.id)}" aria-label="Удалить задачу">${icon('close')}</button></div>`).join(''):empty('Задач пока нет','Добавьте задачу и свяжите её с проектом.','list')}</section>`}
function settingsPage(){return sectionTitle('Настройки','Локальная панель · без внешних запросов при открытии')+`<div class="settings-grid"><section class="panel info-card"><h2>${icon('refresh')}Источники данных</h2><dl><dt>Репозиторий</dt><dd>${external('https://github.com/'+snapshot.source.repository,snapshot.source.repository)}</dd><dt>Версия источника</dt><dd><code>${e(snapshot.source.commit.slice(0,7))}</code></dd>${Object.entries(snapshot.servers).map(([id,s])=>`<dt>Сервер ${id}</dt><dd>${e(when(s.collected_at,true))}</dd>`).join('')}<dt>Режим</dt><dd>Сохранённый снимок</dd></dl><div class="button-row">${button('Перечитать файлы','refresh','refresh')}${button('Импорт JSON','import','upload')}</div><p class="muted-small">Импортируйте полный snapshot.json или выберите вместе links.json, github-repos.json, system-graph.json каталог projects.json и файлы server-*.json. Импорт заменяет снимок только в этом браузере.</p><button class="text-button" data-action="reset-snapshot">Вернуться к снимку из папки сайта</button></section><section class="panel info-card"><h2>${icon('lock')}Приватность</h2><p>Сайт работает с локальными файлами. Внешних шрифтов, аналитики и запросов к AI нет.</p><p>Адрес запуска: <code>127.0.0.1:8080</code>. Сервер доступен только на вашем компьютере.</p><p>GitHub и внешние ссылки открываются только по нажатию.</p><div class="notice">Живой API не настроен. Токены и пароли не нужно вводить в панель.</div></section><section class="panel info-card"><h2>${icon('download')}Резервная копия панели</h2><p>Экспорт включает снимок, ваши локальные проекты и задачи. Сохраните файл перед переносом в другой браузер.</p><div class="button-row">${button('Экспортировать всё','export','download')}${button('Экспортировать снимок','export-snapshot','download')}</div></section><section class="panel info-card"><h2>${icon('moon')}Внешний вид</h2><label class="setting-toggle"><input id="quiet-toggle" type="checkbox" ${compact?'checked':''}> Мягкое свечение</label><p class="muted-small">Уменьшает яркость неоновых акцентов и фона. Системная настройка уменьшения движения учитывается автоматически.</p><button class="text-button" data-action="profile">Профиль владельца</button></section></div>`}
function searchPage(){const q=query.trim().toLowerCase(),ps=data.projects.filter(p=>[p.name,p.repo,p.note,...(p.catalog?.tags||[]),...(p.catalog?.repos||[]).map(r=>r.name),...(p.paths||[]),...(p.domains||[]),...(p.catalog?.folders||[]).map(f=>[f.real_path,f.was].join(' ')),...(p.catalog?.problems||[])].join(' ').toLowerCase().includes(q)),ss=data.services.filter(s=>[s.name,s.description,s.workdir].join(' ').toLowerCase().includes(q)),ds=data.databases.filter(d=>[d.name,d.path,...d.tables.map(t=>t.table)].join(' ').toLowerCase().includes(q));return sectionTitle('Поиск',`«${e(query)}» · ${ps.length+ss.length+ds.length} результатов`,button('Сбросить','clear-search','close'))+`<h2 class="subheading">Проекты · ${ps.length}</h2><div class="project-grid">${ps.map(projectTile).join('')}</div><h2 class="subheading">Сервисы · ${ss.length}</h2><div class="search-results">${ss.map(s=>`<button class="panel search-row" data-service="${e(s.server+':'+s.name)}">${icon('server')}<span>${e(s.name)}<small>${e(s.workdir)}</small></span><b>Сервер ${s.server}</b></button>`).join('')}</div><h2 class="subheading">Базы и таблицы · ${ds.length}</h2><div class="search-results">${ds.map(d=>`<button class="panel search-row" data-db="${e(d.id)}">${icon('db')}<span>${e(d.name)}<small>${e(d.path||d.container)}</small></span><b>${d.tables.length} таблиц</b></button>`).join('')}</div>${ps.length+ss.length+ds.length?'':empty('Ничего не найдено','Попробуйте название проекта, сервиса или таблицы.','search')}`}
function graphPage(){
 const g=data.graph,selected=g.nodes.find(n=>n.id===graphSelected);let nodes=g.nodes;
 if(selected){const connected=new Set([selected.id,...g.edges.filter(e=>e.from===selected.id||e.to===selected.id).flatMap(e=>[e.from,e.to])]);nodes=nodes.filter(n=>connected.has(n.id))}
 else if(graphType!=='all')nodes=nodes.filter(n=>n.type===graphType);
 const types=['server','project','service','container','domain','database'].filter(t=>nodes.some(n=>n.type===t));
 const labels={server:'Серверы',project:'Проекты',service:'Сервисы',container:'Контейнеры',domain:'Домены',database:'Базы данных'};
 const cols=types.map(t=>nodes.filter(n=>n.type===t)),height=Math.max(430,...cols.map(ns=>ns.length*61+80)),width=Math.max(800,types.length*250+40),positions=new Map();
 cols.forEach((ns,c)=>ns.forEach((n,i)=>positions.set(n.id,{x:c*250+20,y:65+i*61})));
 const edges=g.edges.filter(ed=>positions.has(ed.from)&&positions.has(ed.to));
 return sectionTitle('Карта системы',`${g.nodes.length} объектов · ${g.edges.length} связей · нажмите узел, чтобы увидеть его окружение`,button('Обзор проектов','route-home','home'))+`<div class="toolbar"><div class="filter-pills"><button data-graphtype="all" class="${graphType==='all'&&!selected?'active':''}">Все</button>${Object.entries(labels).map(([t,l])=>`<button data-graphtype="${t}" class="${graphType===t&&!selected?'active':''}">${l}</button>`).join('')}</div>${selected?button('Сбросить выделение','reset-graph','close'):''}</div>${selected?`<div class="panel graph-selection"><strong>${e(selected.label)}</strong><span>${e(selected.type)} · ${edges.length} связей</span><button class="text-button" data-node-details="${e(selected.id)}">Подробности ${icon('chevron')}</button></div>`:''}<section class="panel graph-scroll" tabindex="0" aria-label="Прокручиваемый граф системы"><div class="full-graph" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}" aria-hidden="true">${edges.map(ed=>{const a=positions.get(ed.from),b=positions.get(ed.to);return `<path d="M${a.x+215} ${a.y+21} C${a.x+255} ${a.y+21},${b.x-35} ${b.y+21},${b.x} ${b.y+21}" class="graph-edge"><title>${e(ed.kind)}</title></path>`}).join('')}</svg>${types.map((t,i)=>`<h3 style="left:${i*250+25}px">${labels[t]} <span>${cols[i].length}</span></h3>`).join('')}${nodes.map(n=>{const p=positions.get(n.id);return `<button class="graph-node ${selected?.id===n.id?'selected':''}" style="left:${p.x}px;top:${p.y}px" data-graphnode="${e(n.id)}" title="${e(n.label)}">${icon(({server:'server',project:'box',service:'settings',container:'box',domain:'globe',database:'db'})[n.type])}<span>${e(n.label)}</span></button>`}).join('')}</div></section><p class="page-note">Карта объединяет инфраструктуру из system-graph.json и все проекты из catalog/projects.json. При фильтрации скрываются связи с невидимыми узлами.</p>`
}
function modal(title,body,subtitle=''){$('#dialog-content').innerHTML=`<div class="dialog-head"><div><h2>${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#detail').open)$('#detail').showModal()}
function openProject(id){const p=project(id);if(!p)return;const [name,ic,c,sub]=look(p),dbs=data.databases.filter(d=>p.catalog?p.catalog.databases.some(db=>db.server===d.server&&db.engine===d.engine&&db.name===(d.path||d.database||d.container)):(p.databases||[]).includes(d.path||`${d.engine}:${d.database||d.container}`));
 modal(name,`<div class="project-detail-top"><span class="tile-icon ${c}">${icon(ic)}</span>${status(p)}<span class="snapshot-tag">${p.local?'Локальный проект':'На дату снимка'}</span></div>${p.catalog?.status_reason?`<p class="status-reason">${e(p.catalog.status_reason)}</p>`:''}<p class="detail-description">${e(p.note||p.repoInfo?.description||sub)}</p>${['low','medium'].includes(p.confidence)?`<div class="notice amber">${icon('alert')}Сопоставление ${p.confidence==='low'?'предварительное':'по имени и пути'}, требует проверки.</div>`:''}<dl><dt>Тип</dt><dd>${e(kindLabels[p.kind]||p.kind)}</dd><dt>Репозиторий</dt><dd>${p.repo?external(p.repoInfo?.url||'https://github.com/V0van200/'+encodeURIComponent(p.repo),p.repo):'Не привязан'}</dd><dt>Сервер</dt><dd>${e(p.server||'Не привязан')}</dd><dt>Источник</dt><dd>${p.local?'Этот браузер':e(snapshot.source.commit.slice(0,7))+' · '+e(when(serverMetrics().collected_at,true))}</dd></dl><h3>Сервисы и контейнеры</h3>${p.matchedServices.length||p.matchedContainers.length?`<div class="detail-list">${p.matchedServices.map(s=>`<button data-service="${e(s.server+':'+s.name)}">${icon('server')}<span>${e(s.name)}</span><small>${e(s.state)}</small>${icon('chevron')}</button>`).join('')}${p.matchedContainers.map(s=>`<div>${icon('box')}<span>${e(s.name)}</span><small>${e(s.status)}</small></div>`).join('')}</div>`:'<p class="muted">Запущенный процесс не подтверждён. Это не означает, что проект удалён.</p>'}<h3>Базы данных</h3>${dbs.length?`<div class="detail-list">${dbs.map(d=>`<button data-db="${e(d.id)}">${icon('db')}<span>${e(d.name)}</span><small>${d.tables.length} таблиц</small>${icon('chevron')}</button>`).join('')}</div>`:'<p class="muted">Базы не сопоставлены.</p>'}${p.domains?.length?`<h3>Домены / маршруты</h3><ul class="plain-list">${p.domains.map(d=>`<li>${icon('globe')}${e(d)}</li>`).join('')}</ul>`:''}${p.paths?.length?`<h3>Каталоги</h3><ul class="plain-list">${p.paths.map(d=>`<li><code>${e(d)}</code></li>`).join('')}</ul>`:''}${catalogDetails(p)}<div class="button-row">${button('Добавить задачу','task-for:'+p.id,'plus')}${p.local?button('Редактировать','edit-project:'+p.id,'settings'):''}</div>`,sub)
}
function catalogDetails(p){
 const c=p.catalog;if(!c)return '';
 return `<h3>Паспорт проекта</h3><dl><dt>Изменён</dt><dd>${e(c.last_change||'Дата неизвестна')}</dd><dt>Объём каталогов</dt><dd>${bytes(c.size_total)}</dd><dt>Стек</dt><dd>${e((c.stack||[]).join(' · ')||'Не определён')}</dd><dt>Участники</dt><dd>${e((c.people||[]).join(', ')||'Не указаны')}</dd>${c.parent?`<dt>Родитель</dt><dd><button class="text-button" data-project="${e(c.parent)}">${e(project(c.parent)?.name||c.parent)}</button></dd>`:''}</dl>${c.problems.length?`<h3>Проблемы · ${c.problems.length}</h3>${c.problems.map(s=>`<div class="notice amber">${icon('alert')}${e(s)}</div>`).join('')}`:''}<h3>Папки и сохранность кода</h3><div class="folder-passports">${c.folders.map(f=>`<div class="folder-passport ${f.broken||f.missing?'broken':''}"><strong>${icon('folder')}Сервер ${e(f.server)} · ${bytes(f.size)}</strong><p class="mono">${e(f.path)}</p>${f.real_path?`<small>Цель: ${e(f.real_path)}</small>`:''}${f.broken||f.missing?`<div class="warning-text">${f.broken?'Ссылка ведёт в отсутствующий каталог':'Каталог не найден'}${f.was?' · '+e(typeof f.was==='string'?f.was:JSON.stringify(f.was)):''}</div>`:`<small>Изменён: ${e(f.last_change||'неизвестно')} · ${e((f.stack||[]).join(', ')||'стек не определён')}</small>`}${f.git?.last_commit?`<p class="mono">${e(f.git.last_commit)}</p>`:''}</div>`).join('')||'<p class="muted">Серверных папок нет в каталоге.</p>'}</div><h3>Репозитории · ${c.repos.length}</h3>${c.repos.map(r=>`<details class="repo-readme"><summary>${icon('git')}${e(r.name)}<span>${e(r.visibility||'неизвестно')}</span></summary><div>${external(r.url,'Открыть GitHub')}<p>${e(r.description||'')}</p><p class="muted-small">${e(r.stack||'')} · ${bytes(r.size)}</p>${r.readme?`<pre>${e(r.readme.replaceAll(' ⏎ ','\n'))}</pre>`:'<p class="muted">README не найден.</p>'}<small>Файлы в корне: ${e((r.root_files||[]).join(', '))}</small></div></details>`).join('')}${c.domains.some(d=>d.routes.length)?`<h3>Маршруты</h3><div class="detail-list">${c.domains.flatMap(d=>d.routes.map(r=>`<div class="route-row"><span>${e(d.name)}<small class="mono">${e(r.path)}</small></span><small>Сервер ${e(r.server)}<br>${e(r.to||'Статический сайт')}</small></div>`)).join('')}</div>`:''}${c.links?.web?.length?`<h3>Ссылки</h3><ul class="plain-list">${c.links.web.map(url=>`<li>${external(url,url)}</li>`).join('')}</ul>`:''}`;
}
function openService(key){const s=data.services.find(s=>s.server+':'+s.name===key);if(!s)return;modal(s.name,`<p>${e(s.description)}</p><dl>${[['Сервер',s.server],['Состояние',s.state+' / '+s.sub],['Включён',s.enabled],['Порты',(s.ports||[]).map(p=>p.join('/')).join(', ')||'Не найдены'],['Память',bytes(s.memory)],['Перезапуски',s.restarts],['С момента',s.since],['Рабочий каталог',s.workdir||'—'],['Unit',s.unit_file],['Источник',when(s.collected,true)]].map(([k,v])=>`<dt>${e(k)}</dt><dd>${e(v)}</dd>`).join('')}</dl><div class="notice">Только просмотр. Панель не перезапускает сервисы и не выполняет команды на сервере.</div>`,'Состояние из снимка')}
function openDatabase(id){
 const d=data.databases.find(d=>d.id===id);if(!d)return;
 let body=`<div class="database-summary"><span>${e(d.engine)} · Сервер ${d.server}</span><span>${d.tables.length} таблиц</span><span>${bytes(d.size)}</span></div><p class="mono muted">${e(d.path||d.container)}</p><div class="notice">Только схема и число строк. Значения из таблиц не загружены.</div>`;
 if(d.engine==='redis')body+=`<pre>${e((d.info||[]).join('\n'))}</pre>`;
 else{
 body+=`<label class="search-box table-search">${icon('search')}<input id="table-search" type="search" placeholder="Найти таблицу или поле…" aria-label="Поиск таблицы или поля"></label><div class="schema-tables">`;
 for(const t of d.tables){
 body+=`<details class="schema-table" data-table-search="${e([t.table,...t.columns.map(c=>c.name)].join(' ').toLowerCase())}"><summary><span>${icon('db')}${e(t.table)}</span><small>${t.columns.length} полей · ${t.rows??'—'} строк</small></summary><div class="table-wrap"><table><thead><tr><th>Поле</th><th>Тип</th><th>Ограничения</th></tr></thead><tbody>`;
 body+=t.columns.map(c=>`<tr><td>${e(c.name)}</td><td><code>${e(c.type)}</code></td><td>${c.pk?'PK ':''}${c.notnull||c.nullable==='NO'?'NOT NULL':''}</td></tr>`).join('');
 body+='</tbody></table></div>';
 if(t.foreign_keys?.length)body+=`<pre>Связи\n${e(JSON.stringify(t.foreign_keys,null,2))}</pre>`;
 body+='</details>';
 }
 body+='</div>';
 if(d.foreign_keys?.length)body+=`<h3>Внешние ключи · ${d.foreign_keys.length}</h3><ul class="plain-list mono">${d.foreign_keys.map(f=>`<li>${e(f.from)} → ${e(f.to)}</li>`).join('')}</ul>`;
 }
 modal(d.name,body,'Структура базы данных');
}
function newProject(existing){const p=existing||{};modal(p.id?'Редактировать проект':'Новый проект',`<form id="project-form" data-edit="${e(p.id||'')}"><label class="field">Название<input name="name" required maxlength="100" placeholder="Название проекта" value="${e(p.name||'')}"></label><label class="field">Тип<select name="kind">${Object.entries(kindLabels).map(([v,l])=>`<option value="${v}" ${p.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Описание<textarea name="note" rows="3" maxlength="2000" placeholder="Идея, назначение или следующий шаг">${e(p.note||'')}</textarea></label><p class="muted-small">Карточка сохранится в этом браузере. Репозиторий и сервер автоматически не создаются.</p><div class="button-row"><button class="button primary" type="submit">Сохранить проект</button>${p.id?`<button class="button danger" type="button" data-delete-project="${e(p.id)}">Удалить локальный проект</button>`:''}</div></form>`)}
function newTask(id=''){modal('Добавить задачу',`<form id="task-form"><label class="field">Задача<input name="title" required maxlength="250" placeholder="Что нужно сделать?"></label><label class="field">Проект<select name="project"><option value="">Общая задача</option>${data.projects.map(p=>`<option value="${e(p.id)}" ${p.id===id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><button class="button primary" type="submit">Добавить</button><p class="muted-small">Задача локальная. Она не отправляется агентам или на сервер.</p></form>`)}
async function refresh(reset=false){try{const next=validateSnapshot(await fetch('./snapshot.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}));if(reset)localStorage.removeItem('vovan:snapshot');const saved=get('snapshot',null);snapshot=saved&&!reset?validateSnapshot(saved):next;data=model(snapshot,custom);lastRead=new Date();shell();toast(saved&&!reset?'Сохранён импортированный снимок. Для исходного выберите «Вернуться к снимку».':'Локальные файлы перечитаны. Это не живой опрос серверов.')}catch{toast('Не удалось прочитать снимок. Текущие данные сохранены.')}}
function validPersonal(p){return Array.isArray(p)&&p.length<=2000&&p.every(v=>v&&typeof v.id==='string'&&/^[\w.-]+$/.test(v.id)&&typeof v.name==='string'&&v.name.length<=100&&typeof v.kind==='string'&&(!v.note||typeof v.note==='string'))}
function validTasks(t){return Array.isArray(t)&&t.length<=10000&&t.every(v=>v&&typeof v.id==='string'&&typeof v.title==='string'&&v.title.length<=250&&typeof v.done==='boolean')}
async function importFiles(files){try{
 if(!files.length)return;
 if([...files].reduce((n,f)=>n+f.size,0)>15*1024*1024)throw Error('Максимальный размер импорта — 15 МБ.');
 const parsed=await Promise.all([...files].map(async f=>({name:f.name,data:JSON.parse(await f.text())})));let next,nextProjects=custom,nextTasks=tasks;
 if(parsed.length===1){const o=parsed[0].data;if(o.format==='vovan-os-backup'){next=o.snapshot;if(!validPersonal(o.projects)||!validTasks(o.tasks))throw Error('Некорректные локальные проекты или задачи.');nextProjects=o.projects;nextTasks=o.tasks}else next=o}
 else{const find=n=>parsed.find(f=>f.name===n)?.data;const servers={};for(const f of parsed){const m=f.name.match(/^server-([\w-]+)\.json$/);if(m)servers[m[1]]=f.data}next={version:1,source:{repository:'V0van200/vovan-os',commit:'imported'},links:find('links.json'),repos:find('github-repos.json'),graph:find('system-graph.json'),catalog:find('projects.json'),servers};if(!Object.keys(servers).length)throw Error('Выберите также файлы server-*.json.');}
 validateSnapshot(next);if(!next.source||typeof next.source.repository!=='string'||typeof next.source.commit!=='string')throw Error('В снимке нет сведений об источнике.');
 // Construct before persistence to avoid accepting incompatible payloads.
 const nextModel=model(next,nextProjects);
 if(!put('snapshot',next))return;
 custom=nextProjects;tasks=nextTasks;put('projects',custom);put('tasks',tasks);snapshot=next;data=nextModel;query='';shell();toast('Снимок импортирован. Данные сохранены в этом браузере.');
 }catch(err){toast('Импорт отменён: '+(err.message||'некорректный JSON'))}finally{$('#import-file').value=''}}
function go(r){query='';if(route===r){shell()}else location.hash=r;document.body.classList.remove('menu-open');$('#detail').close()}
document.addEventListener('click',ev=>{
 const t=ev.target.closest('button,a');if(!t)return;
 if(t.matches('.nav-item'))document.body.classList.remove('menu-open');
 if(t.dataset.route){go(t.dataset.route);return}
 if(t.dataset.project){openProject(t.dataset.project);return}
 if(t.dataset.repo){const p=data.projects.find(p=>(p.catalog?.repos||[{name:p.repo}]).some(pr=>pr.name===t.dataset.repo));if(p)openProject(p.id);return}
 if(t.dataset.service){openService(t.dataset.service);return}
 if(t.dataset.db){openDatabase(t.dataset.db);return}
 if(t.dataset.favorite){viewState.favorite=viewState.favorite.includes(t.dataset.favorite)?viewState.favorite.filter(x=>x!==t.dataset.favorite):[...viewState.favorite,t.dataset.favorite];put('favorites',viewState.favorite);renderPage();return}
 if(t.dataset.v2View){viewState.view=t.dataset.v2View;renderPage();return}
 if(t.dataset.v2Folder){viewState.fileGroup=t.dataset.v2Folder;renderPage();return}
 if(t.dataset.selectBot){viewState.selectedBot=t.dataset.selectBot;renderPage();return}
 if(t.dataset.theme||t.dataset.accent){changeAppearance(t.dataset.theme?'theme':'accent',t.dataset.theme||t.dataset.accent);renderPage();return}
 if(['source-info','db-info','deploy-info','bot-info'].includes(t.dataset.action)){modal('Подключение источников','<p>Сейчас панель читает локальный снимок. Живые метрики, команды серверов и потоки событий ещё не подключены.</p><p>Схемы баз, паспорта проектов и состояния сервисов доступны по карточкам. Новый снимок можно импортировать в настройках.</p>');return}
 if(t.dataset.action==='all-folders'){viewState.fileGroup='all';renderPage();return}
 if(t.dataset.mapfilter){mapFilter=t.dataset.mapfilter;renderPage();return}
 if(t.dataset.projectfilter){projectFilter=t.dataset.projectfilter;renderPage();return}
 if(t.dataset.dbfilter){dbFilter=t.dataset.dbfilter;renderPage();return}
 if(t.dataset.graphtype){graphType=t.dataset.graphtype;graphSelected=null;renderPage();return}
 if(t.dataset.graphnode){graphSelected=t.dataset.graphnode;$('#detail').close();renderPage();return}
 if(t.dataset.nodeDetails){const n=data.graph.nodes.find(n=>n.id===t.dataset.nodeDetails);if(n.type==='project')openProject(({'eeklera-backend':'eeklera-services',media:'streaming','misc-78':'server-misc'})[n.id.replace('project:','')]||n.id.replace('project:',''));else modal(n.label,`<dl>${Object.entries(n).filter(([k])=>!['id','label'].includes(k)).map(([k,v])=>`<dt>${e(k)}</dt><dd>${e(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl><h3>Связи</h3><div class="detail-list">${data.graph.edges.filter(ed=>ed.from===n.id||ed.to===n.id).map(ed=>{const other=ed.from===n.id?ed.to:ed.from;return `<button data-graphnode="${e(other)}" data-action="close"><span>${e(data.graph.nodes.find(n=>n.id===other)?.label||other)}</span><small>${e(ed.kind)}</small></button>`}).join('')}</div>`);return}
 if(t.dataset.app!=null){const a=data.apps[+t.dataset.app];modal(a.name,`<dl><dt>Путь</dt><dd class="mono">${e(a.path)}</dd><dt>Сервер</dt><dd>${a.server}</dd><dt>Размер</dt><dd>${bytes(a.size)}</dd><dt>Стек</dt><dd>${e(a.stack.join(', ')||'Не определён')}</dd><dt>Git</dt><dd><pre>${e(a.git?JSON.stringify(a.git,null,2):'Не найден')}</pre></dd></dl><div class="notice">Это каталог из инвентаризации. Локальная панель не имеет доступа к файлам сервера.</div>`);return}
 if(t.dataset.deleteTask){tasks=tasks.filter(x=>x.id!==t.dataset.deleteTask);put('tasks',tasks);renderPage();return}
 if(t.dataset.deleteProject){custom=custom.filter(p=>p.id!==t.dataset.deleteProject);put('projects',custom);data=model(snapshot,custom);$('#detail').close();shell();toast('Локальная карточка удалена.');return}
 const a=t.dataset.action;if(!a)return;
 if(a.startsWith('route-')){go(a.slice(6));return}
 if(a.startsWith('task-for:')){newTask(a.slice(9));return}
 if(a.startsWith('edit-project:')){newProject(custom.find(p=>p.id===a.slice(13)));return}
 const actions={close:()=>$('#detail').close(),'new-project':()=>newProject(),'new-task':()=>newTask(),menu:()=>document.body.classList.toggle('menu-open'),quiet:()=>{compact=!compact;put('compact',compact);shell()},refresh:()=>refresh(),'reset-snapshot':()=>refresh(true),import:()=>$('#import-file').click(),export:()=>download('vovan-os-backup.json',{format:'vovan-os-backup',snapshot,projects:custom,tasks}),'export-snapshot':()=>download('snapshot.json',snapshot),'clear-search':()=>{query='';shell()},'reset-graph':()=>{graphSelected=null;renderPage()},profile:()=>modal('Vovan',`<div class="profile-summary"><span class="avatar">V</span><div><h3>Владелец</h3><p>Локальное рабочее пространство</p></div></div><p>Ваши задачи и проекты сохраняются в этом браузере. Авторизация на внешних серверах не подключена.</p><button class="button" data-action="route-settings">Настройки и резервная копия</button>`) };actions[a]?.();
});
document.addEventListener('input',ev=>{const t=ev.target;if(t.id==='global-search'){query=t.value;renderPage()}if(t.id==='table-search'){const q=t.value.toLowerCase();document.querySelectorAll('[data-table-search]').forEach(d=>d.hidden=!d.dataset.tableSearch.includes(q))}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.hasAttribute('data-v2-kind')){viewState.kind=t.value;renderPage()}if(t.hasAttribute('data-v2-sort')){viewState.sort=t.value;renderPage()}if(t.dataset.pref){changeAppearance(t.dataset.pref,t.checked)}if(t.id==='server-select'){selectedServer=t.value;put('server',selectedServer);shell()}if(t.id==='quiet-toggle'){compact=t.checked;put('compact',compact);document.body.classList.toggle('quiet',compact)}if(t.dataset.task){tasks=tasks.map(x=>x.id===t.dataset.task?{...x,done:t.checked}:x);put('tasks',tasks);renderPage()}if(t.id==='import-file')importFiles(t.files)});
document.addEventListener('submit',ev=>{
 if(ev.target.id==='project-form'){ev.preventDefault();const f=ev.target,fd=new FormData(f),name=String(fd.get('name')).trim();if(!name)return;const p={id:f.dataset.edit||'local-'+crypto.randomUUID(),name,kind:fd.get('kind'),note:String(fd.get('note')).trim(),local:true};custom=f.dataset.edit?custom.map(x=>x.id===p.id?p:x):[...custom,p];put('projects',custom);data=model(snapshot,custom);$('#detail').close();shell();toast('Проект сохранён локально.');}
 if(ev.target.id==='task-form'){ev.preventDefault();const fd=new FormData(ev.target),title=String(fd.get('title')).trim();if(!title)return;tasks=[...tasks,{id:crypto.randomUUID(),title,project:fd.get('project'),done:false}];put('tasks',tasks);$('#detail').close();renderPage();toast('Задача добавлена.');}
});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';query='';projectFilter='all';document.body.classList.remove('menu-open');shell();window.scrollTo(0,0)});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();$('#global-search')?.focus()}if(ev.key==='Escape'){document.body.classList.remove('menu-open');if(query){query='';shell()}}});
$('#detail').addEventListener('click',ev=>{if(ev.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('#detail').close()}});
try{const saved=get('snapshot',null);try{snapshot=validateSnapshot(saved||await fetch('./snapshot.json').then(r=>{if(!r.ok)throw Error('Нет файла snapshot.json');return r.json()}))}catch(err){if(!saved)throw err;localStorage.removeItem('vovan:snapshot');snapshot=validateSnapshot(await fetch('./snapshot.json').then(r=>r.json()))}data=model(snapshot,custom);shell()}catch(err){$('#app').innerHTML=`<div class="initial-load"><strong>VOVAN <span>OS</span></strong><h1>Не удалось открыть снимок</h1><p>${e(err.message)}</p><p>Запустите START.bat или python3 start.py из папки сайта.</p><a href="./">Повторить</a></div>`;console.error(err)}

document.addEventListener('submit',ev=>{if(ev.target.id==='v2-profile'){ev.preventDefault();const f=new FormData(ev.target);put('profile',Object.fromEntries(f));toast('Профиль сохранён локально');renderPage()}});
